let ai=0,auto=1;function tab(i){ai=i;document.getElementById("tb5").innerHTML=NM.map((n,j)=>'<button data-i="'+j+'" class="'+(j==i?"on":"")+'">'+ic(n,j==i)+n+"</button>").join("");document.getElementById("scr").textContent=NM[i]}
