(function(){/* project timeline: 3D staircase */
const tl=document.getElementById("tl"),tot=DUR.reduce((a,d)=>a+d[2],0);let w=0;
const C=[["#0e2f78","#071c52","#3a64c9","rgba(40,90,230,.7)"],["#2c66d8","#1b4bb3","#6aa0ff","rgba(50,110,255,.65)"],["#44a8ee","#2386d4","#97d6ff","rgba(70,170,255,.65)"],["#2fc2a4","#169a82","#86f0d6","rgba(40,200,170,.6)"],["#62c24f","#37a03c","#b0ee94","rgba(100,220,80,.65)"]];
const DEF={Discover:"Research families and competitors to understand how people store and share their asset details.",Define:"Turn the research into a clear problem statement, user needs and goals for the app.",Ideate:"Sketch ideas and paper wireframes, then shape the best flows and the information structure.",Design:"Build the style guide and high-fidelity screens into a clickable prototype for every flow.",Test:"Check the prototype with real users, find usability issues and refine the screens."};
const CK='<span class="sxo"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span>';
const PIN=c=>'<svg class="sxpin" viewBox="0 0 30 38" aria-hidden="true"><path d="M15 36C15 36 3 22 3 14a12 12 0 0124 0c0 8-12 22-12 22z" fill="'+c[1]+'" stroke="'+c[2]+'" stroke-width="2"/><circle cx="15" cy="14" r="5" fill="'+c[2]+'"/></svg>';
const SH='<span class="sxpf"></span><svg class="sxs" viewBox="0 0 100 116" aria-hidden="true"><defs><linearGradient id="sxg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff"/><stop offset=".5" stop-color="#c3cadb"/><stop offset="1" stop-color="#8f98b0"/></linearGradient></defs><path d="M50 4L92 18v38c0 29-19 49-42 58C27 105 8 85 8 56V18z" fill="url(#sxg)"/><path d="M50 12L84 24v32c0 23-15 40-34 48C31 96 16 79 16 56V24z" fill="#0b2a6b"/><path d="M32 58l13 13 25-27" fill="none" stroke="#eef2fb" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/></svg>';
tl.innerHTML='<div class="sxw" id="sxw"><svg class="sxr" aria-hidden="true"><path id="sxrp" d=""/></svg>'+DUR.map((d,i)=>{const a=w+1,e=w+d[2];w=e;const c=C[i]||C[C.length-1];
return '<div class="sxb" style="--k:'+i+';--c1:'+c[0]+';--c2:'+c[1]+';--c3:'+c[2]+';--g:'+c[3]+'">'+PIN(c)+(i==DUR.length-1?SH:"")+'<span class="sxn">0'+(i+1)+'</span><div class="sxt"><h4>'+d[0]+'<span class="sxp">'+(a==e?"Week "+a:"Weeks "+a+"\u2013"+e)+'</span></h4><p class="sxd">'+(DEF[d[0]]||"")+'</p></div><div class="sxc"><span class="sxk"><b>'+d[2]+'</b><i>weeks</i></span>'+CK+'</div></div>'}).join("")+'</div><p class="dtot">'+tot+' weeks \u00b7 about 4 months in total</p>';
const wrap=document.getElementById("sxw"),rp=document.getElementById("sxrp");
function route(){const r=wrap.getBoundingClientRect(),ps=[...wrap.querySelectorAll(".sxpin")].map(p=>{const q=p.getBoundingClientRect();return{x:q.left-r.left+q.width/2,y:q.top-r.top+q.height-4}});
if(ps.length<2){return}let d="M"+(ps[0].x-34)+" "+(ps[0].y+62)+" Q"+(ps[0].x-30)+" "+(ps[0].y+10)+" "+ps[0].x+" "+ps[0].y;
for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i],m=(a.y-b.y)*.5;d+=" C"+(a.x-46)+" "+(a.y-m)+" "+(b.x-46)+" "+(b.y+m)+" "+b.x+" "+b.y}
rp.setAttribute("d",d)}
route();addEventListener("resize",route);if(window.ResizeObserver)new ResizeObserver(route).observe(wrap);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(route);
new IntersectionObserver((es,o)=>es.forEach(en=>{if(en.isIntersecting){tl.classList.add("in");o.disconnect()}}),{threshold:.25}).observe(tl)})();

(function(){/* paper wireframes lightbox */
const pw=document.getElementById("pw");if(!pw)return;
const bs=[...pw.querySelectorAll(".pw-i")];let cur=0,lb=null;
function show(i){cur=(i+bs.length)%bs.length;const b=bs[cur],im=lb.querySelector("img"),s=b.querySelector("img");im.src=s.src;im.alt=s.alt;lb.querySelector(".pwl-t").textContent=(cur+1)+" / "+bs.length+" \u00b7 "+b.dataset.t}
function close(){lb.classList.remove("on");document.body.style.overflow=""}
function open(i){if(!lb){lb=document.createElement("div");lb.className="pwl";lb.innerHTML='<button class="pwl-x" aria-label="Close">\u00d7</button><button class="pwl-p" aria-label="Previous">\u2039</button><img alt=""><button class="pwl-n" aria-label="Next">\u203a</button><div class="pwl-t"></div>';document.body.appendChild(lb);lb.addEventListener("click",e=>{const c=e.target.classList;if(e.target===lb||c.contains("pwl-x"))close();else if(c.contains("pwl-p"))show(cur-1);else if(c.contains("pwl-n"))show(cur+1)})}lb.classList.add("on");show(i);document.body.style.overflow="hidden"}
bs.forEach((b,i)=>b.addEventListener("click",()=>open(i)));
addEventListener("keydown",e=>{if(!lb||!lb.classList.contains("on"))return;if(e.key==="Escape")close();else if(e.key==="ArrowLeft")show(cur-1);else if(e.key==="ArrowRight")show(cur+1)})})();

